using CTXD.Server.Data;using Npgsql;
namespace CTXD.Server.Services;
public sealed record VipBenefitView(int Vip,int Sequence,string Kind,int Amount,bool Claimed,bool Available);
public sealed record VipView(int VipLevel,bool TeamTimesClaimed,int TeamTimes,int TeamTimesReward,VipBenefitView[] Benefits);
public sealed record VipClaimResult(int Vip,int Sequence,string Kind,int Amount);
public sealed class VipService(GameDb db,CanonicalContent content,IPlayerItemInventory items,GamePushHub push)
{
 const string Initial="1#00#00#10#00#00#0#0#0#0#0";
 static readonly (int vip,int seq,string kind,int charge,int itemIndex)[] Rules=[(2,1,"freeConstruction",55,0),(2,2,"item",65,4),(3,1,"phantom",56,0),(3,2,"item",66,1),(4,2,"item",67,7),(5,2,"item",68,11),(6,2,"item",70,13),(7,1,"teamTimes",71,0)];
 public async Task<VipView> GetAsync(long player,CancellationToken ct){await using var c=await db.DataSource.OpenConnectionAsync(ct);await EnsureAsync(c,null,player,ct);await using var q=new NpgsqlCommand("SELECT p.consume_level,p.team_times,v.vip_status FROM players p JOIN player_vip_runtime v ON v.player_id=p.id WHERE p.id=$1",c);q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("PLAYER_NOT_FOUND","Player does not exist.",404);return View(r.GetInt32(0),r.GetInt32(1),r.GetString(2));}
 public Task<VipView> ClaimTeamTimesAsync(long player,CancellationToken ct)=>ClaimInternalAsync(player,7,1,ct);
 public async Task<VipClaimResult> ClaimAsync(long player,int vip,int sequence,CancellationToken ct){var rule=Rules.FirstOrDefault(x=>x.vip==vip&&x.seq==sequence);if(rule==default)throw new GameException("VIP_BENEFIT_INVALID","Legacy VIP benefit does not exist.",404);var view=await ClaimInternalAsync(player,vip,sequence,ct);var benefit=view.Benefits.Single(x=>x.Vip==vip&&x.Sequence==sequence);return new(vip,sequence,benefit.Kind,benefit.Amount);}
 async Task<VipView> ClaimInternalAsync(long player,int vip,int sequence,CancellationToken ct){var rule=Rules.Single(x=>x.vip==vip&&x.seq==sequence);await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await EnsureAsync(c,t,player,ct);int level,times;string status;await using(var q=new NpgsqlCommand("SELECT p.consume_level,p.team_times,v.vip_status FROM players p JOIN player_vip_runtime v ON v.player_id=p.id WHERE p.id=$1 FOR UPDATE OF p,v",c,t)){q.Parameters.AddWithValue(player);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("PLAYER_NOT_FOUND","Player does not exist.",404);level=r.GetInt32(0);times=r.GetInt32(1);status=r.GetString(2);}if(level<vip)throw new GameException("VIP_LEVEL_REQUIRED",$"Legacy VIP {vip} is required.",403);if(Claimed(status,vip,sequence))throw new GameException("VIP_BENEFIT_CLAIMED","VIP benefit was already claimed.",409);if(vip==7){await using var f=new NpgsqlCommand("SELECT 1 FROM player_functions WHERE player_id=$1 AND function_id=59",c,t);f.Parameters.AddWithValue(player);if(await f.ExecuteScalarAsync(ct)is null)throw new GameException("TEAM_LOCKED","Team function 59 must be open.",403);}var amount=Amount(rule.charge);var changed=SetClaimed(status,vip,sequence);await using(var ledger=new NpgsqlCommand("INSERT INTO player_vip_claims(player_id,vip_level,sequence,reward_key) VALUES($1,$2,$3,$4);UPDATE player_vip_runtime SET vip_status=$5,updated_at=now() WHERE player_id=$1",c,t)){ledger.Parameters.AddWithValue(player);ledger.Parameters.AddWithValue(vip);ledger.Parameters.AddWithValue(sequence);ledger.Parameters.AddWithValue(rule.kind);ledger.Parameters.AddWithValue(changed);await ledger.ExecuteNonQueryAsync(ct);}if(rule.kind=="freeConstruction"){await using var add=new NpgsqlCommand("UPDATE players SET free_construction_num=free_construction_num+$2 WHERE id=$1",c,t);add.Parameters.AddWithValue(player);add.Parameters.AddWithValue(amount);await add.ExecuteNonQueryAsync(ct);}else if(rule.kind=="phantom"){await using var add=new NpgsqlCommand("UPDATE players SET phantom_tokens=phantom_tokens+$2 WHERE id=$1",c,t);add.Parameters.AddWithValue(player);add.Parameters.AddWithValue(amount);await add.ExecuteNonQueryAsync(ct);}else if(rule.kind=="teamTimes"){await using var add=new NpgsqlCommand("UPDATE players SET team_times=team_times+$2 WHERE id=$1;INSERT INTO player_team_time_grants(player_id,source_key,amount) VALUES($1,'vip:7:1',$2)",c,t);add.Parameters.AddWithValue(player);add.Parameters.AddWithValue(amount);await add.ExecuteNonQueryAsync(ct);times+=amount;}else{var item=content.Items.Values.SingleOrDefault(x=>x.Type==13&&x.Index==rule.itemIndex)??throw new GameException("VIP_ITEM_STATIC_MISSING","Legacy VIP token item is missing.",500);await items.GrantAsync(c,t,player,item.Id,item.Type,amount,ct);}await t.CommitAsync(ct);await push.SendAsync(player,"vip.updated",new{vip,sequence,rule.kind,amount},ct);if(rule.kind=="teamTimes")await push.SendAsync(player,"team.updated",new{reason="vip7.1",teamTimes=times},ct);return View(level,times,changed);}
 VipView View(int level,int times,string status)=>new(level,Claimed(status,7,1),times,Amount(71),Rules.Select(x=>new VipBenefitView(x.vip,x.seq,x.kind,Amount(x.charge),Claimed(status,x.vip,x.seq),level>=x.vip)).ToArray());
 int Amount(int charge)=>content.ChargeItems.TryGetValue(charge,out var item)?(int)item.Param:throw new GameException("VIP_STATIC_MISSING",$"ChargeItem {charge} is missing.",500);
 static async Task EnsureAsync(NpgsqlConnection c,NpgsqlTransaction? t,long player,CancellationToken ct){await using var q=new NpgsqlCommand("INSERT INTO player_vip_runtime(player_id,vip_status) SELECT id,$2 FROM players WHERE id=$1 ON CONFLICT DO NOTHING",c,t);q.Parameters.AddWithValue(player);q.Parameters.AddWithValue(Initial);await q.ExecuteNonQueryAsync(ct);}
 static bool Claimed(string status,int vip,int seq){var rows=status.Split('#');return rows.Length>=vip&&rows[vip-1].Length>=seq&&rows[vip-1][seq-1]=='1';}
 static string SetClaimed(string status,int vip,int seq){var rows=status.Split('#');if(rows.Length<vip)throw new GameException("VIP_STATE_INVALID","VIP state is malformed.",500);var chars=rows[vip-1].ToCharArray();if(chars.Length<seq)throw new GameException("VIP_STATE_INVALID","VIP privilege state is malformed.",500);chars[seq-1]='1';rows[vip-1]=new string(chars);return string.Join('#',rows);}
}
